T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader counts too."] = "길드 관리자는 왕관 > 모듈 > 공격대 & 전리품에서 공대장을 지정해요. 진행 중인 공격대에서는 공대장도 포함돼요."
