T["Oasis can do a lot. Pick what you want to use - the rest stays off for now and can be turned on anytime under 'Discover'."] = "Oasis는 기능이 많아요. 쓸 것을 고르세요 - 나머지는 꺼져 있고 언제든 '탐색'에서 켤 수 있어요."
T["Oasis reads Blizzard's built-in damage meter after every fight - in instances too."] = "Oasis는 전투마다 Blizzard 내장 피해 표시를 읽어요 - 인스턴스에서도."
