T["Stats: +healing, intellect, spirit, mp5;Weapon: staff or one-hander + off-hand with healing;Healing: Rejuvenation and Regrowth ahead, Healing Touch for big hits;Tip: Innervate for mana, Rebirth for fallen healers"] = "능력치: +치유, 지능, 정신력, 마나 회복;무기: 지팡이 또는 한손 무기 + 치유 보조장비;치유: 회복과 재생 미리, 큰 피해엔 치유의 손길;팁: 마나엔 정신 자극, 쓰러진 치유사엔 환생"
T["Stats: +healing, intellect, spell crit (Illumination refunds mana), mp5;Weapon: one-hander + off-hand/shield with healing;Healing: Flash of Light for small damage, Holy Light (low rank) for big hits;Tip: hand out blessings, Divine Protection when you pull aggro"] = "능력치: +치유, 지능, 주문 치명타 (깨달음이 마나 반환), 마나 회복;무기: 한손 무기 + 치유 보조장비/방패;치유: 작은 피해엔 빛의 섬광, 큰 피해엔 성스러운 빛 (낮은 등급);팁: 축복 배분, 끌려가면 신의 보호"
T["Stats: +healing, mp5, intellect - spirit does little;Weapon: one-hander + shield with healing;Healing: Chain Heal for groups, Healing Wave (low rank) for the tank;Tip: drop Mana Spring Totem, Earth Shield on the tank"] = "능력치: +치유, 마나 회복 (MP5), 지능 - 정신력은 효과 적음;무기: 한손 무기 + 치유 방패;치유: 파티엔 연쇄 치유, 방어엔 치유의 물결 (낮은 등급);팁: 마나 샘 토템 설치, 방어에게 대지의 보호막"
T["Stats: +healing, spirit (Meditation: regen while casting), intellect, mp5;Weapon: staff or one-hander + off-hand with healing, wand;Healing: Renew and Power Word: Shield ahead, Greater Heal (low rank) for the tank;Tip: Prayer of Healing for the group, Fade on aggro"] = "능력치: +치유, 정신력 (명상: 시전 중에도 회복), 지능, 마나 회복;무기: 지팡이 또는 한손 무기 + 치유 보조장비, 마법봉;치유: 소생과 신의 권능: 보호막 미리, 방어엔 상급 치유 (낮은 등급);팁: 파티엔 치유의 기원, 어그로엔 소실"
T["Stats: armor (bear form multiplies it), stamina, agility (dodge + armor);Weapon: damage doesn't matter - only the stats (staff/polearm with stamina);Rotation: Maul, Swipe for packs, Demoralizing Roar;Tip: strength for more threat, Enrage to start"] = "능력치: 방어도 (곰 변신이 배로 늘림), 체력, 민첩성 (회피 + 방어도);무기: 피해와 무관 - 능력치만 중요 (체력 붙은 지팡이/장창);순환: 할퀴기, 파티엔 휘둘러치기, 위협의 포효;팁: 위협 수준엔 힘, 시작에 격노"
T["Stats: strength (1 point = 2 AP), agility (AP + crit), crit, hit up to +9 %;Weapon: damage doesn't matter - only the stats;Rotation: Claw/Shred for combo points, then Ferocious Bite;Tip: powershift (recast form) for energy, open from stealth"] = "능력치: 힘 (1점 = 전투력 2), 민첩성 (전투력 + 치명타), 치명타, 적중 +9 %까지;무기: 피해와 무관 - 능력치만 중요;순환: 할퀴기/칼날 발톱으로 연계 점수, 그다음 흉포한 이빨;팁: 기력엔 변신 재시전, 은신에서 기습"
T["Stats: strength (1 point = 2 AP), crit (procs Flurry = faster swings), hit up to +9 %;Weapon: slow two-hander - Windfury procs per swing, so slower = more damage;Rotation: Windfury Weapon, Stormstrike, Earth Shock;Tip: Strength of Earth and Windfury Totem for the group"] = "능력치: 힘 (1점 = 전투력 2), 치명타 (질풍 발동 = 빠른 공격), 적중 +9 %까지;무기: 느린 양손 무기 - 질풍은 타격마다 발동, 느릴수록 피해 증가;순환: 질풍의 무기, 폭풍의 일격, 대지 충격;팁: 파티에 대지력 토템과 질풍의 토템"
T["Stats: strength (1 point = 2 AP), crit, hit up to +9 %;Weapon: slow two-hander - seals and Judgement scale per swing;Rotation: Seal of Righteousness/Command, Judgement, reapply seal;Tip: Consecration only with enough mana, Blessing of Might on yourself"] = "능력치: 힘 (1점 = 전투력 2), 치명타, 적중 +9 %까지;무기: 느린 양손 무기 - 문장과 심판은 타격마다;순환: 정의/지휘의 문장, 심판, 문장 다시 걸기;팁: 신성화는 마나 충분할 때만, 자신에겐 힘의 축복"
T["Stats: hit up to +9 %, agility (1 AP, ~29 = 1 % crit), AP, crit;Weapon: Combat = fast off-hand, slow main hand (Sinister Strike); daggers for Backstab;Rotation: build combo points, keep Slice and Dice up, then Eviscerate;Tip: dual wielding misses white hits more often - hit matters most"] = "능력치: 적중 +9 %까지, 민첩성 (전투력 1, 약 29 = 치명타 1 %), 전투력, 치명타;무기: 전투 = 빠른 보조장비, 느린 주무기 (사악한 일격); 기습엔 단검;순환: 연계 점수 쌓기, 난도질 유지, 그다음 절개;팁: 쌍수는 일반 공격이 더 자주 빗나가요 - 적중이 가장 중요"
T["Stats: hit up to +9 %, agility (2 ranged AP, ~53 = 1 % crit), AP, intellect;Weapon: slow ranged weapon (big damage per shot), melee weapon for stats;Rotation: Hunter's Mark, Auto Shot, Aimed Shot/Multi-Shot in between;Tip: feed your pet and keep it happy, Freezing Trap (square) for control"] = "능력치: 적중 +9 %까지, 민첩성 (원거리 전투력 2, 약 53 = 치명타 1 %), 전투력, 지능;무기: 느린 원거리 무기 (발사당 높은 피해), 능력치 붙은 근접 무기;순환: 사냥꾼의 징표, 자동 사격, 사이사이 조준 사격/일제 사격;팁: 동반자는 먹여서 기분 좋게, 얼음의 덫(네모)로 제어"
T["Stats: hit up to +9 %, strength (1 point = 2 AP), crit (~20 agility = 1 %);Weapon: slow two-hander (Mortal Strike, Heroic Strike scale per swing);Rotation: build rage, Mortal Strike / Bloodthirst, Whirlwind, spare rage into Heroic Strike;Tip: Battle Shout before the pull, Execute below 20 % health"] = "능력치: 적중 +9 %까지, 힘 (1점 = 전투력 2), 치명타 (민첩성 약 20 = 1 %);무기: 느린 양손 무기 (필사의 일격, 영웅의 일격은 타격마다);순환: 분노 쌓기, 필사의 일격 / 피의 갈증, 소용돌이, 남는 분노는 영웅의 일격;팁: 전투 전 전투의 외침, 생명력 20 % 미만엔 마무리 일격"
T["Stats: defense (440 = crit immune vs bosses at 60), stamina, armor, block;Weapon: one-hander + shield, fast weapon = more rage;Rotation: Shield Slam/Revenge, Sunder Armor on the target, Heroic Strike with high rage;Tip: hit helps so Taunt and abilities don't miss"] = "능력치: 방어 (440 = 60레벨 보스 상대 치명타 면역), 체력, 방어도, 방패 막기;무기: 한손 무기 + 방패, 빠른 무기 = 분노 증가;순환: 방패 가격/복수, 대상에 방어구 가르기, 분노 많으면 영웅의 일격;팁: 적중은 도발과 기술이 빗나가지 않게 도와요"
T["Stats: defense, stamina, armor, then spell damage for more threat;Weapon: one-hander (ideally spell damage) + shield;Rotation: Righteous Fury on, Consecration for packs, keep Holy Shield up;Tip: mana is tight - use Seal of Wisdom or some intellect"] = "능력치: 방어, 체력, 방어도, 그다음 위협 수준용 주문 피해;무기: 한손 무기 (주문 피해 붙으면 좋음) + 방패;순환: 정의의 격노 켜기, 파티엔 신성화, 신성한 방패 유지;팁: 마나가 부족해요 - 지혜 또는 지능의 문장 챙기기"
T["Stats: spell damage, spell crit (Elemental Focus saves mana), intellect, mp5;Weapon: one-hander + shield/off-hand with spell damage;Rotation: spam Lightning Bolt, Chain Lightning on packs, Flame Shock;Tip: spell hit up to +16 % in raids, Mana Spring Totem against oom"] = "능력치: 주문 피해, 주문 치명타 (정기의 집중이 마나 절약), 지능, 마나 회복;무기: 한손 무기 + 주문 피해 방패/보조장비;순환: 번개 화살 연타, 파티엔 연쇄 번개, 화염 충격;팁: 공격대에선 주문 적중 +16 %까지, 마나 부족엔 마나 샘 토템"
T["Stats: spell damage, spell crit, intellect, spell hit up to +16 % in raids;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Moonfire + Insect Swarm, then Wrath or Starfire;Tip: Innervate yourself when mana runs low"] = "능력치: 주문 피해, 주문 치명타, 지능, 공격대에선 주문 적중 +16 %까지;무기: 지팡이 또는 한손 무기 + 주문 피해 보조장비;순환: 달빛 섬광 + 곤충 떼, 그다음 천벌 또는 별빛 화살;팁: 마나 부족하면 자신에게 정신 자극"
T["Stats: spell damage, spell hit up to +16 % (raid), stamina, intellect;Weapon: staff or dagger + off-hand with spell damage, wand for leftover mana;Rotation: Corruption + curse, then Shadow Bolt; Life Tap instead of drinking;Tip: stamina pays off twice (Life Tap, Voidwalker/Soul Link)"] = "능력치: 주문 피해, 주문 적중 +16 %까지 (공격대), 체력, 지능;무기: 지팡이 또는 단검 + 주문 피해 보조장비, 남은 마나엔 마법봉;순환: 부패 + 저주, 그다음 어둠의 화살; 마시기 대신 생명력 전환;팁: 체력은 두 배로 유용 (생명력 전환, 공허방랑자/영혼 연결)"
T["Stats: spell damage, spell hit up to +16 % (raid), spirit for mana;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Shadow Word: Pain, Mind Blast, Mind Flay;Tip: stay in Shadowform, Vampiric Embrace heals the group"] = "능력치: 주문 피해, 주문 적중 +16 %까지 (공격대), 마나엔 정신력;무기: 지팡이 또는 한손 무기 + 주문 피해 보조장비;순환: 어둠의 권능: 고통, 정신 분열, 정신의 채찍;팁: 어둠의 형상 상시 유지, 흡혈의 선물이 파티 치유"
T["Stats: spell damage, then spell hit up to +16 % (raid bosses), intellect, spell crit;Weapon: staff with spell damage, plus a wand for leftover mana;Rotation: spam Frostbolt or Fireball, Evocation when out of mana;Leveling: intellect and spirit = less downtime, sheep (moon) in groups"] = "능력치: 주문 피해, 그다음 주문 적중 +16 %까지 (공격대 보스), 지능, 주문 치명타;무기: 주문 피해 지팡이, 남은 마나엔 마법봉;순환: 얼음 화살 또는 화염구 연타, 마나 바닥엔 환기;레벨 업: 지능과 정신력 = 휴식 감소, 파티에선 양(달) 걸기"
