T["1.  Keep the combat log on (Settings > Areas > Combat board, on by default).\n2.  After playing, double-click ImportCrits.bat in the Oasis folder.\n3.  /reload in game - your highest crit shows here and is shared with the guild."] = "1.  전투 기록을 켜 두세요 (설정 > 영역 > 전투 순위, 기본으로 켜져 있어요).\n2.  플레이 후 Oasis 폴더의 ImportCrits.bat을 더블클릭하세요.\n3.  게임에서 /reload - 최고 치명타가 여기에 표시되고 길드와 공유돼요."
