T["Active: meme sounds, music and guild emojis are included."] = "활성: 밈 사운드, 음악, 길드 이모지가 포함돼 있어요."
T["Active members below the officer ranks appear in the 'Promotion' list after this many days in the same rank. 0 = off."] = "임원 등급 아래의 활동 중인 길드원은 같은 등급으로 이 일수가 지나면 '승급' 목록에 표시돼요. 0 = 끔."
T["Current zone first"] = "현재 지역 먼저"
T["All areas, grouped by topic: guild, playing together, raid, trade, fun. Click a heading to collapse its group."] = "모든 영역을 주제별로 묶었어요: 길드, 함께 플레이, 공격대, 거래, 재미. 제목을 클릭하면 묶음이 접혀요."
T["Expand all zones"] = "모든 지역 펼치기"
T["Collapse all zones"] = "모든 지역 접기"
T["All members with rank, level and Oasis version. Right-click a row: change rank."] = "모든 길드원의 등급, 레벨, Oasis 버전. 줄을 우클릭: 등급 변경."
T["All fonts under the SIL Open Font License 1.1"] = "모든 글꼴은 SIL Open Font License 1.1 적용"
T["All: Burning Adrenaline: run out of the raid AT ONCE (you are about to die).\nAll: Full resources at the start - use everything.\nTank: Set a tank order (Adrenaline on the tank).\nDD: Not in front of or behind the dragon."] = "All: 불타는 아드레날린: 즉시 공격대 밖으로 이동 (곧 죽어요).\nAll: 시작 시 자원 가득 - 전부 쏟아붓기.\nTank: 탱커 순서 정하기 (탱커에게 아드레날린).\nDD: 용의 앞이나 뒤에 서지 않기."
T["All: Do not let the 8 Firesworn die near the raid (explosion).\nTank: Each add tank pulls their Firesworn away, warlocks banish.\nHealer: Dispel, keep an eye on the add tanks.\nDD: Garr first, adds only when called."] = "All: Firesworn 8마리를 공격대 근처에서 죽이지 않기 (폭발).\nTank: 쫄 탱커는 각자 Firesworn을 멀리 끌고 가기, 흑마법사는 추방.\nHealer: 해제, 쫄 탱커 주시.\nDD: 가르 먼저, 쫄은 지시가 있을 때만."
T["All: Tank the two Core Ragers away from the boss, do not kill them.\nTank: Swap the Golemagg tank when Magma Splash stacks too high.\nDD: Only on Golemagg."] = "All: 심장부 맹수 두 마리는 보스에게서 떨어뜨려 탱킹, 죽이지 않기.\nTank: 용암 튀기기 중첩이 너무 높으면 골레마그 탱커 교대.\nDD: 골레마그만 공격."
T["All: The 4 priests first, they heal each other.\nTank: Keep Sulfuron and the priests apart.\nDD: Interrupt! Stop the priests' Dark Mending."] = "All: 사제 4마리 먼저, 서로 치유해요.\nTank: 설퍼론과 사제들을 떨어뜨리기.\nDD: 차단! 사제의 암흑의 치유 끊기."
T["All: Fire protection! Wrath of Ragnaros knocks melee back - then get back in.\nAll: Sons phase (after 3 min or when he submerges): kill all Sons of Flame.\nTank: Second tank ready when the first is knocked away.\nHealer: Spread out, ranged not too close (Lava Burst).\nDD: Melee: keep mana under control, ranged keep your distance."] = "All: 화염 저항! Wrath of Ragnaros가 근접을 날려요 - 그 뒤 다시 붙기.\nAll: 피조물 단계 (3분 후 또는 잠수 시): Sons of Flame 모두 처치.\nTank: 첫 탱커가 날아가면 두 번째 탱커 대기.\nHealer: 산개, 원거리는 너무 가까이 가지 않기 (용암 폭발).\nDD: 근접: 마나 관리, 원거리는 거리 유지."
T["All: Flame Buffet stacks - ranged behind pillars to let it drop.\nTank: Two tanks behind pillars, Wing Buffet knocks back.\nDD: Onyxia Scale Cloak required."] = "All: 화염 강타 중첩 - 원거리는 기둥 뒤에서 중첩 해소.\nTank: 탱커 두 명 기둥 뒤, 폭풍 날개가 밀쳐내요.\nDD: 오닉시아 비늘 망토 필수."
T["All: Remove Gehennas' Curse (reduced healing) at once.\nAll: Get out of the Rain of Fire.\nTank: Tank the two Flamewakers apart.\nDD: Flamewakers first, then Gehennas."] = "All: 게헨나스의 저주 (치유량 감소) 즉시 해제.\nAll: 불의 비에서 벗어나기.\nTank: 불꽃지기 두 마리를 떨어뜨려 탱킹.\nDD: 불꽃지기 먼저, 그다음 게헨나스."
T["All: Remove Lucifron's Curse and Impending Doom at once (mages/druids, priests/paladins).\nTank: Tank the two guards apart - mind control!\nHealer: Spread out, dispel mind-controlled players.\nDD: Guards first, then Lucifron."] = "All: 루시프론의 저주와 파멸의 예언 즉시 해제 (마법사/드루이드, 사제/성기사).\nTank: 경비병 두 마리를 떨어뜨려 탱킹 - 정신 지배!\nHealer: 산개, 정신 지배당한 플레이어 해제.\nDD: 경비병 먼저, 그다음 루시프론."
T["All: Living Bomb: run out of the raid AT ONCE!\nAll: Inferno - away from the boss, dispel Ignite Mana.\nTank: Hold the middle, step out briefly on Inferno.\nDD: Melee back off on Inferno."] = "All: 살아있는 폭탄: 즉시 공격대 밖으로 이동!\nAll: 불지옥 - 보스에게서 떨어지기, 마나 점화 해제.\nTank: 중앙 유지, 불지옥 때 잠시 빠지기.\nDD: 근접은 불지옥 때 물러나기."
T["All: Watch the guards' magic reflection/damage shield - stop damage then.\nTank: One guard per tank, mages sheep the elite guards.\nDD: Healer guards (Flamewaker Healer) first."] = "All: 경비병의 마법 반사/피해 보호막 주의 - 그때는 공격 중지.\nTank: 탱커 한 명당 경비병 하나, 마법사는 정예 경비병 변이.\nDD: 치유 경비병 (Flamewaker Healer) 먼저."
T["All: Never stand in front of or behind Onyxia (breath and tail sweep).\nAll: Phase 2 (65%): dodge fireballs, stay out of the cave entrances.\nAll: Phase 3 (40%): fear - Fear Ward/Tremor Totem ready, avoid the lava cracks.\nTank: Onyxia sideways at the wall, head away from the raid.\nTank: Phase 2: pick up the whelps. Phase 3: get aggro back at once.\nHealer: Tank has priority, spread out in phase 2.\nDD: Wait for 3 attacks of the tank. Phase 2: whelps first."] = "All: 오닉시아의 앞이나 뒤에 절대 서지 않기 (숨결과 꼬리 휘두르기).\nAll: 2단계 (65%): 화염구 피하기, 동굴 입구에 들어가지 않기.\nAll: 3단계 (40%): 공포 - 공포의 수호물/진동의 토템 준비, 용암 균열 피하기.\nTank: 오닉시아를 벽 쪽에 옆으로, 머리는 공격대 반대로.\nTank: 2단계: 새끼용 모으기. 3단계: 즉시 어그로 되찾기.\nHealer: 탱커 우선, 2단계에는 산개.\nDD: 탱커가 3번 공격할 때까지 대기. 2단계: 새끼용 먼저."
T["All: Panic - Fear Ward/Tremor Totem, hunters: Tranquilizing Shot on Frenzy.\nAll: Get out of the lava fire on the ground.\nTank: Magmadar with his back to the raid.\nDD: Ranged spread out at the back."] = "All: 공황 - 공포의 수호물/진동의 토템, 사냥꾼: 광기에 평정의 사격.\nAll: 바닥의 용암 불길에서 벗어나기.\nTank: 마그마다르의 등이 공격대를 향하게.\nDD: 원거리는 뒤쪽에 산개."
T["All: Phase 1: dragonkin from both sides, watch the class calls.\nAll: Phase 3 (20%): the skeletons rise again - kill them again.\nTank: Nefarian at the wall, fear - Fear Ward.\nHealer: Class call for priests: healing hurts - be careful.\nDD: Hunters/warriors: watch the class calls (weapons gone, stance)."] = "All: 1단계: 양쪽에서 용족 등장, 직업 호출 주의.\nAll: 3단계 (20%): 해골이 다시 일어나요 - 다시 처치.\nTank: 네파리안을 벽 쪽에, 공포 - 공포의 수호물.\nHealer: 사제 직업 호출: 치유가 피해를 줘요 - 주의.\nDD: 사냥꾼/전사: 직업 호출 주의 (무기 파괴, 태세)."
T["All: Phase 1: destroy the eggs (mind control via the orb), pick up the adds.\nAll: After all eggs: boss in the room - Fire Nova.\nTank: Gather the adds at the stairs.\nDD: Mages and dragonkin first."] = "All: 1단계: 알 파괴 (수정구로 정신 지배), 쫄 잡기.\nAll: 알을 모두 부순 뒤: 보스가 방으로 - 화염 회오리.\nTank: 쫄을 계단에 모으기.\nDD: 마법사와 용족 먼저."
T["All: Frenzy - hunters: Tranquilizing Shot.\nTank: Two tanks, watch Wing Buffet.\nDD: Onyxia Scale Cloak required."] = "All: 광기 - 사냥꾼: 평정의 사격.\nTank: 탱커 두 명, 폭풍 날개 주의.\nDD: 오닉시아 비늘 망토 필수."
T["All: Shadow of Ebonroc heals the boss - the tank with the debuff swaps.\nTank: Two tanks swap on Shadow.\nDD: Onyxia Scale Cloak required."] = "All: 에본로크의 그림자가 보스를 치유해요 - 디버프 걸린 탱커 교대.\nTank: 탱커 두 명이 그림자 때 교대.\nDD: 오닉시아 비늘 망토 필수."
T["All: Knockback - stand against the wall.\nTank: Two tanks, aggro is split by Knock Away.\nDD: Mortal Strike on the tank: healers be prepared."] = "All: 밀쳐내기 - 벽에 붙어 서기.\nTank: 탱커 두 명, 날려버리기로 어그로가 나뉘어요.\nDD: 탱커에게 죽음의 일격: 힐러 대비."
T["All: He teleports - whoever has aggro, do not run away.\nAll: Remove Shazzrah's Curse, Arcane Explosion: melee keep your distance.\nTank: Get back on him right after every blink.\nHealer: Dispel (Deaden Magic)."] = "All: 순간이동해요 - 어그로를 가진 사람은 도망가지 않기.\nAll: 샤즈라의 저주 해제, 신비한 폭발: 근접은 거리 유지.\nTank: 점멸할 때마다 바로 다시 붙기.\nHealer: 해제 (마법 약화)."
T["All: Two of the five breath types per week - avoid the breath behind the corner.\nAll: Hourglass Sand for the Bronze affliction.\nTank: Tank at the gate, raid behind the corner.\nDD: Tranquilizing Shot on Frenzy."] = "All: 매주 다섯 가지 숨결 중 두 가지 - 숨결은 모퉁이 뒤에서 피하기.\nAll: 청동 고통에는 모래시계 모래.\nTank: 문에서 탱킹, 공격대는 모퉁이 뒤.\nDD: 광기에 평정의 사격."
T["Hold Alt: all stats and scoring details. Shift: Blizzard comparison."] = "Alt 누르기: 모든 능력치와 평가 상세. Shift: Blizzard 비교."
T["Release Alt: compact view. Shift: Blizzard comparison."] = "Alt 떼기: 간단히 보기. Shift: Blizzard 비교."
T["Old Oasis"] = "구버전 Oasis"
T["On: drag it anywhere with the mouse. Off: docked to the talent window."] = "켬: 마우스로 원하는 곳에 끌어 놓기. 끔: 특성 창에 붙음."
T["Leader of the Darkspear"] = "검은창 부족의 지도자"
T["Unsent text stays when you switch conversations"] = "보내지 않은 글은 대화를 바꿔도 남아 있어요"
