T["Detailed cards"] = "상세 카드"
T["Expand"] = "펼치기"
T["Logout: Blizzard's dialog list was tainted by Oasis (fixed in 0.5.478 - please update Oasis)."] = "접속 종료: Blizzard의 대화창 목록이 Oasis의 영향을 받았어요 (0.5.478에서 수정 - Oasis를 업데이트해 주세요)."
T["Banner on the overview: Midas, the auction house add-on by Rebo of the guild OASIS"] = "개요의 배너: 길드 OASIS의 Rebo가 만든 경매장 애드온 Midas"
T["Suggest promotion after"] = "승급 제안 기준"
T["Next roll you're done for!"] = "다음 주사위에서는 끝장이야!"
T["Sample data is only available in the developer version."] = "예시 데이터는 개발자 버전에만 있어요."
T["Enable areas"] = "영역 켜기"
T["Ready for the pull? Readiness, enchants and buffs per player"] = "풀링 준비됐나요? 플레이어별 준비 상태, 마법부여, 버프"
T["Confirmed critical hit records imported from the log file."] = "확인된 치명타 기록을 로그 파일에서 가져왔어요."
T["beta gift"] = "베타 선물"
T["Distribute loot automatically when you are master looter"] = "전리품 담당자일 때 전리품 자동 분배"
T["Loot council from rank"] = "전리품 위원회 최소 등급"
T["Frames / sec"] = "프레임 / 초"
T["Frames over 1 ms (this session): %d"] = "1 ms 초과 프레임 (이번 세션): %d"
T["Please enter the name of a guild member (not one of your own characters)."] = "길드원의 이름을 입력하세요 (내 캐릭터 제외)."
T["Blocked"] = "차단됨"
T["A block of %s was observed; its cause has not been confirmed."] = "%s 차단이 감지됐어요. 원인은 확인되지 않았어요."
T["Boss of the Defias"] = "데피아즈단의 두목"
T["Boss of Ratchet - everything has its price"] = "톱니항의 두목 - 모든 것에는 값이 있다"
T["Boss positions in the dungeon atlas and drop chances of dungeon bosses – GPL-2.0. Authors: Lag, Daviesh and others"] = "던전 지도의 보스 위치와 던전 보스 드롭 확률 - GPL-2.0. 제작: Lag, Daviesh 외"
T["Bosses & loot"] = "보스 & 전리품"
