T["Cairne Bloodhoof"] = "케른 블러드후프"
T["Casual: Select"] = "Casual: 선택"
T["Casual: Confirm"] = "Casual: 확인"
T["Casual: Window open"] = "Casual: 창 열기"
T["Casual: Window close"] = "Casual: 창 닫기"
T["Casual: Notice"] = "Casual: 알림"
T["Casual: Click"] = "Casual: 클릭"
T["Casual: Switch"] = "Casual: 스위치"
T["Character statistic – highest single value, critical status unknown"] = "캐릭터 통계 - 최고 단일 수치, 치명타 여부 알 수 없음"
T["Chat input and spell commands may be involved."] = "채팅 입력과 주문 명령이 관련됐을 수 있어요."
T["Chat input and target changes may be involved."] = "채팅 입력과 대상 변경이 관련됐을 수 있어요."
T["Chat messages require direct input in this client."] = "이 클라이언트에서는 채팅 메시지를 직접 입력해야 해요."
T["Credits"] = "크레딧"
T["Critical heal"] = "치명타 치유"
T["Critical hit import belongs to another character."] = "치명타 가져오기가 다른 캐릭터의 것이에요."
T["Check critical hit source"] = "치명타 출처 확인"
T["Critical hit records imported from the combat log files."] = "치명타 기록을 전투 기록 파일에서 가져왔어요."
T["Count crits automatically when fighting alone"] = "혼자 싸울 때 치명타 자동 집계"
T["Estimate crits in groups and dungeons"] = "파티와 던전에서 치명타 추정"
T["The X on the window collapses Oasis into the bar. The X on the bar closes it completely."] = "창의 X는 Oasis를 바로 접어요. 바의 X는 완전히 닫아요."
T["The yellow exclamation mark on the icon marks this."] = "아이콘의 노란 느낌표가 이것을 알려줘요."
T["That was just luck! Again!"] = "그건 운이었어! 한 번 더!"
T["That's it. You can find the tour again any time under Settings > Status or with /oa rundgang."] = "이게 전부예요. 안내는 설정 > 상태 또는 /oa rundgang으로 언제든 다시 볼 수 있어요."
T["Data"] = "데이터"
T["Opaque"] = "불투명"
T["Your character"] = "내 캐릭터"
T["Your stats: Oasis rank, badges and all counters"] = "내 통계: Oasis 등급, 휘장, 모든 집계"
T["You can find the download in the guild's Discord."] = "다운로드는 길드 Discord에서 찾을 수 있어요."
T["The client does not let Oasis enable combat logging - please type /combatlog yourself."] = "클라이언트가 Oasis의 전투 기록 켜기를 허용하지 않아요 - /combatlog를 직접 입력해 주세요."
T["The content of the selected area. The overview shows who is online, what is coming up and what is new."] = "선택한 영역의 내용이에요. 개요에서는 누가 접속 중인지, 예정된 일과 새 소식을 보여줘요."
T["The minimap button or /oa opens Oasis. The dash at the top right turns the window into a slim bar."] = "미니맵 버튼이나 /oa로 Oasis를 열어요. 오른쪽 위의 선을 누르면 창이 얇은 바로 바뀌어요."
T["The officer channel (/o) with history - only for ranks with officer chat permission."] = "임원 채널 (/o)과 기록 - 임원 채팅 권한이 있는 등급 전용."
T["The yellow bar on the left of the list marks this."] = "목록 왼쪽의 노란 선이 이것을 알려줘요."
T["Close details"] = "상세 닫기"
T["Clear default sound for online notices"] = "접속 알림에 또렷한 기본음"
T["Character statistics are unavailable in this client."] = "이 클라이언트에서는 캐릭터 통계를 사용할 수 없어요."
T["Guild leadership has muted sound effects for you."] = "길드 운영진이 내 효과음을 차단했어요."
T["The bar is there from login and stays - the X on the window only closes the window."] = "바는 접속할 때부터 계속 표시돼요 - 창의 X는 창만 닫아요."
T["The percentage compares the item's score for your role, not your total damage. Effects are estimates."] = "퍼센트는 총 피해량이 아니라 내 역할 기준 아이템 점수를 비교해요. 효과는 추정치예요."
T["The statistic currently provides no readable value."] = "통계에서 지금은 읽을 수 있는 값이 없어요."
T["Your guild's hub. In 30 seconds you will know your way around - here is what matters."] = "우리 길드의 중심이에요. 30초면 익힐 수 있어요 - 중요한 것만 알려드릴게요."
T["The protected function was blocked. The exact cause is still unknown."] = "보호된 기능이 차단됐어요. 정확한 원인은 아직 알 수 없어요."
T["The matching character statistic has not been found yet."] = "맞는 캐릭터 통계를 아직 찾지 못했어요."
T["The full license texts are in the Oasis folder: CREDITS.txt, LICENSE and LICENSE-MIT.txt."] = "전체 라이선스 문서는 Oasis 폴더에 있어요: CREDITS.txt, LICENSE, LICENSE-MIT.txt."
T["These guild ranks (0 = guild master) may vote in the loot council."] = "이 길드 등급 (0 = 길드장)이 전리품 위원회에서 투표할 수 있어요."
T["This character is on a different WoW account and named you as their main. They only count as your alt in the guild if you confirm."] = "이 캐릭터는 다른 WoW 계정에 있고 나를 본캐로 등록했어요. 확인해야만 길드에서 내 부캐로 인정돼요."
T["This client provides no add-on metrics (C_AddOnProfiler missing)."] = "이 클라이언트는 애드온 측정값을 제공하지 않아요 (C_AddOnProfiler 없음)."
T["Discord Voice"] = "Discord 음성"
