T["Otherwise: ':' + 2 letters shows matching emojis, Tab inserts."] = "아니면: ':' + 글자 2개로 이모지를 보여 주고 Tab으로 넣습니다."
T["Otherwise: the item tooltip shows which of your characters has it and how many."] = "아니면: 아이템 툴팁에 어느 캐릭터가 몇 개 가졌는지 표시합니다."
T["Otherwise: green arrow up = better, red arrow down = worse (bags, loot window)."] = "아니면: 초록 위 화살표 = 더 좋음, 빨간 아래 화살표 = 더 나쁨 (가방, 전리품 창)."
T["Otherwise: green arrow when an item is better for your class and role."] = "아니면: 직업과 역할에 더 좋은 아이템에 초록 화살표를 표시합니다."
T["Hide bag bar"] = "가방 바 숨기기"
T["The B key still opens your bags."] = "B 키로 여전히 가방을 열 수 있습니다."
T["How well prepared the sign-ups are - and what the raid lead requires per raid"] = "신청자의 준비 상태 - 그리고 공대장이 공격대별로 요구하는 것"
end)
